const stageTextures = {};

export const STAGE_ART = {
  ragnarok: 'data:image/jpeg;base64,',
  velara: 'data:image/jpeg;base64,',
  gorvath: 'data:image/jpeg;base64,',
  malphas: 'data:image/jpeg;base64,',
  seraphine: 'data:image/jpeg;base64,',
  voidfang: 'data:image/jpeg;base64,',
  morvane: 'data:image/jpeg;base64,',
  frostqueen: 'data:image/jpeg;base64,',
  paleking: 'data:image/jpeg;base64,'
};

/* Wandering arenas — not tied to any fighter, just two unnamed
   judgement-courtyard designs. Any match has a 20% chance of landing
   in one of these instead of either fighter's home stage. */
export const RANDOM_STAGE_ART = [
  { id: 'courtyard', src: 'data:image/jpeg;base64,' },
  { id: 'clocksanctuary', src: 'data:image/jpeg;base64,' }
];
export const RANDOM_STAGE_CHANCE = 0.2;

export const STAGE_THEMES = {
  velara: { id: 'velara', name: 'Velara Vault' },
  ragnarok: { id: 'ragnarok', name: 'Ragnarok Rift' },
  inferna: { id: 'inferna', name: 'Inferna Furnace' },
  seraphine: { id: 'seraphine', name: 'Seraphine Spire' },
  morvane: { id: 'morvane', name: 'Morvane Mirage' },
  ashborn: { id: 'ashborn', name: 'Ashborn Bastion' },
  gorvath: { id: 'gorvath', name: 'Gorvath Quay' },
  malphas: { id: 'malphas', name: 'Malphas Hollow' },
  grendel: { id: 'grendel', name: 'Grendel Maw' },
  frostqueen: { id: 'frostqueen', name: 'Frostqueen Citadel' },
  paleking: { id: 'paleking', name: 'Paleking Plaza' },
  voidfang: { id: 'voidfang', name: 'Voidfang Verge' },
  shitler: { id: 'shitler', name: 'Shitler Shrine' },
  courtyard: { id: 'courtyard', name: 'Judgement Courtyard' },
  clocksanctuary: { id: 'clocksanctuary', name: 'Clock Sanctuary' }
};

function formatThemeName(key) {
  const str = String(key || 'courtyard').replace(/[-_]+/g, ' ');
  return str.replace(/\b\w/g, function (char) { return char.toUpperCase(); });
}

export function getFighterHomeStage(fighter = {}) {
  const fighterId = fighter && (fighter.id || fighter);
  const key = STAGE_ART[fighterId] ? fighterId : 'courtyard';
  const theme = STAGE_THEMES[key] || { id: key, name: formatThemeName(key) };
  return {
    ...theme,
    src: STAGE_ART[key] || (RANDOM_STAGE_ART.find((stage) => stage.id === key)?.src) || null
  };
}

export function getStageThemeForMatch(t1 = {}, t2 = {}) {
  const leftId = t1 && (t1.id || t1);
  const rightId = t2 && (t2.id || t2);

  if (RANDOM_STAGE_ART.length && Math.random() < RANDOM_STAGE_CHANCE) {
    const pick = RANDOM_STAGE_ART[Math.floor(Math.random() * RANDOM_STAGE_ART.length)];
    return { id: pick.id, name: pick.name || formatThemeName(pick.id), src: pick.src };
  }

  const homeKey = STAGE_ART[leftId] ? leftId : (STAGE_ART[rightId] ? rightId : null);
  const key = homeKey || 'courtyard';
  const theme = STAGE_THEMES[key] || { id: key, name: formatThemeName(key) };
  return { ...theme, src: STAGE_ART[key] || (RANDOM_STAGE_ART.find((stage) => stage.id === key)?.src) || null };
}

export function getStageBannerText(t1 = {}, t2 = {}) {
  return getStageThemeForMatch(t1, t2).name;
}

function getStageTexture(id, src) {
  if (!stageTextures[id]) {
    stageTextures[id] = new THREE.TextureLoader().load(src);
  }
  return stageTextures[id];
}

export function applyStage(stageState, t1, t2) {
  const { scene, backdropGroup, defaultFog } = stageState;
  const theme = getStageThemeForMatch(t1, t2);
  const tex = theme.src ? getStageTexture(theme.id, theme.src) : null;

  if (tex) {
    scene.background = tex;
    scene.fog = null;
    backdropGroup.visible = false;
  } else {
    scene.background = new THREE.Color(0x0b0a0d);
    scene.fog = defaultFog;
    backdropGroup.visible = true;
  }

  return theme;
}



